\begin{abstract}
Model reduction techniques have emerged as a powerful paradigm across different fronts of scientific computing. Despite their success, the provided tools and methodologies remain limited if high-dimensional dynamical systems subject to initial uncertainty and/or stochastic noise are encountered; in particular if rare events are of interest. We address this open challenge by borrowing ideas from Mori-Zwanzig formalism and Chorin's optimal prediction method. The novelty of our work lies on employing time-dependent optimal projection of the dynamic on a desired set of resolved variables. We show several theoretical and numerical properties of our model reduction approach. In particular, we show that the devised surrogate trajectories are consistent with the probability flow of the full-order system. Furthermore, we identify the measure underlying the projection through polynomial chaos expansion technique. This allows us to efficiently compute the projection even for trajectories that are initiated on low probability events. Moreover, we investigate the introduced model-reduction error of the surrogate trajectories on a standard setup, characterizing the convergence behaviour of the scheme. Several numerical results highlight the computational advantages of the proposed scheme in comparison to Monte-Carlo and optimal prediction method. Through this framework, we demonstrate that by tracking the measure along with the consistent projection of the dynamic we are able to access accurate estimates of different statistics  including observables conditional on a given initial configuration.
\end{abstract}

\noindent Throughout the paper, we adopt the following conventions. Coordinates in the state space are denoted by lowercase letters, e.g., $x$, while random variables are written in uppercase, e.g., $X$, unless stated otherwise. A random variable $X$ with law (probability distribution) $\mu$ is an element of $L^2(\Omega,\mathcal{A},\mathbb{P})$, the Hilbert space of square-integrable random variables on the probability space $(\Omega,\mathcal{A},\mathbb{P})$. A stochastic process is a family $\{X_t\}_{t\in\mathcal{T}}$ of random variables indexed by time, whose marginal laws $\{\mu_t\}_{t\in\mathcal{T}}$ define the probability flow. When $\mu_t$ is absolutely continuous with respect to the Lebesgue measure, we denote its probability density by $\rho_t$, so that $d\mu_t(x)=\rho_t(x)\,dx$. We denote by $L^2(\mathbb{R}^d,\mu)$ the space of measurable functions on $\mathbb{R}^d$ that are square-integrable with respect to $\mu$. \\ \ \\
As polynomial bases will be employed later to represent random variables (e.g., through PC expansions) we introduce the notation of the multi-index  $a=(a_1,\ldots,a_n)\in\mathbb{N}^n$, which has length $|a|=\sum_{i=1}^n a_i$ and defines monomials $x^a=\prod_{i=1}^n x_i^{a_i}$. For an integer $r\ge0$, we denote by $\mathcal{I}_r^n=\{a\in\mathbb{N}^n:|a|\le r\}$ the set of all multi-indices of degree at most $r$, so that a polynomial of degree $\le r$ can be written as $\sum_{a\in \mathcal{I}_r^n} c_a x^a$ with coefficients $c_a\in\mathbb{R}$. \\ \ \\
Given a random variable $X$ and a sub-$\sigma$-algebra $\mathcal{G}\subseteq\mathcal{A}$, we denote by $\mathbb{E}[X|\mathcal{G}]$ the conditional expectation, which represents the orthogonal projection of $X$ onto the subspace of $\mathcal{G}$-measurable random variables. When conditioning on another random variable $Y$, we write $\mathbb{E}[X|Y]$ as shorthand for $\mathbb{E}[X|\sigma(Y)]$, where $\sigma(Y)$ is the smallest $\sigma$-algebra with respect to which $Y$ is measurable. For a state vector $X\in\Gamma\subseteq\mathbb{R}^N$ with law $\mu$, and a measurable map $A:\Gamma\to\mathbb{R}^m$ defining the resolved variables 
$\hat X=A(X)$,

the law of $\hat X$ is the pushforward $\hat{\mu}=A_\#\mu$. The conditional expectation $\mathbb{E}[g(X)|\hat X]$ is then the orthogonal projection of $g\in L^2(\Gamma,\mu)$ onto $L^2(\mathbb{R}^m,\hat\mu)$. We denote this projection by $P[g](\hat X)$ and its complement by $Q[g](\hat X)$. We further introduce a {time-dependent projection operator} $P_t$, defined as the conditional expectation with respect to the current probability law $\mu_t$, i.e. 
\begin{eqnarray}
P_t g &=& \mathbb{E}_{\mu_t}[\,g(X_t)\mid \hat{X}_t\,]. \nonumber
\end{eqnarray}

\noindent For dynamical systems, we consider both deterministic and stochastic cases.
Let $(\Omega, \mathcal{F},(\mathcal{F}_t)_{t\geq 0},P)$ be a filtered probability space, $\Gamma \subset\mathbb{R}^N$ the phase space and the state vector $X\in\Gamma\subseteq\mathbb{R}^N$.
Consider the deterministic dynamics,
\begin{eqnarray}\label{eq:ode assumption}
    dX_t = b(X_t,t)dt, \qquad    X_0\sim \mu_0,
\end{eqnarray}
with flow map $X_t=\Phi(X_0,t)$ and generator (Liouville operator) $L=\sum_{i=1}^N b_i \,\partial_{x_i}$. For such systems, we denote by $e^{tL}$ the semigroup of operators generated by $L$, so that $u(t)=e^{tL}u(0)$ solves the corresponding evolution equation.
A stochastic system is modeled by the $\Gamma$-valued stochastic process $\{X_t\}_{t\geq 0}, \ X_t\in L^2(\Omega;\mathbb{R}^N)$, governed by the Itô SDE,
\begin{eqnarray}\label{eq:sde assumption}
    dX_t = b(X_t,t)dt + \sigma(X_t,t)dW_t,\qquad    X_0\sim \mu_0,
\end{eqnarray}
with the drift vector $b:\Gamma\times\mathbb{R}\rightarrow\mathbb{R}^N$, and where the noise term arises from the $q$-dimensional Wiener process $W_t$ with independent components and the $N\times q$ matrix of noise coefficients $\sigma:\Gamma\times\mathbb{R}\rightarrow \mathbb{R}^{N\times q}$. In this stochastic case, the associated generator is
\begin{eqnarray}
    L=\sum_i b_i \,\partial_{x_i} + \sum_{i,j} D_{ij}\,\partial_{x_i}\partial_{x_j}, \qquad D=\tfrac12 \sigma\sigma^\top .
\end{eqnarray}
We also consider the corresponding probability flows,
\begin{equation}\label{eq:mut}
    \partial_t\mu_t=\mathcal{L}\mu_t,
\end{equation}
where $\mathcal{L}=L^*$ consists of the Kolmogorov forward operator $\mathcal{L}=-\sum_{i=1}^N\partial_{x_i}b_i$ or $\mathcal{L}=-\sum_{i=1}^N\partial_{x_i}b_i+\sum_{i=1}^N\partial_{x_i}\partial_{x_j}D_{ij}$, respectively, and $L^*$ denotes the adjoint of the generator $L$ of either process.
We define the resolved variables $\hat{X}:=A(X)=\{A_i(X)\}_{i=\{1,\dots,m\}}\in\hat{\Gamma}, \ A_i:\Gamma\to\hat{\Gamma}_i\subseteq\mathbb{R}$, where $\hat{\Gamma}=\hat{\Gamma}_1\times\dots\times\hat{\Gamma}_m$.

\noindent Consider the high-dimensional deterministic system with uncertain initial condition
\begin{eqnarray} \label{eq:ode1}
\dot{X}_t &=& b(X_t,t), \ \  \qquad X(0)=X_0 \sim \mu_0, \quad X\in\Gamma\subseteq\mathbb{R}^N.
\end{eqnarray}




We are interested in the evolution of a set of resolved variables $\,\hat{X}\in\hat{\Gamma}\subseteq\mathbb{R}^m$ ($m\ll N$), with the full state decomposed as $X=(\hat{X},\hat{X}^{\perp})$. The central question is: { How can one construct surrogate trajectories for $\mathbb{E}[\hat{X}_t|\hat{X}_0]$ that are exact in law, i.e. consistent with the marginal probability flow $\hat{\mu}_t$ of the resolved variables?}
Classical approaches face following limitations.
\begin{itemize}
\item The MZ formalism provides an exact reduction, but introduces an intractable memory integral that requires knowledge of the full system.
\item Monte Carlo sampling is exact in law but converges slowly, and becomes impractical when conditioning on rare events. 
\item Solving the Liouville or Fokker–Planck equations yields the probability flow, but does not provide trajectories or multi-time statistics.
\end{itemize}
As a motivating example, consider Hamiltonian molecular dynamics: although the full system may involve thousands of degrees of freedom, one is often interested only in a few relevant or collective coordinates. Similarly, in network dynamics, attention may focus on the evolution of a handful of hub nodes rather than describing all peripheral components. In both cases, reduced models that remain consistent in law with the marginal statistics of the selected variables are crucial for efficient prediction and analysis. \\ \ \\
Our goal is to design a framework that overcomes these obstacles and extends naturally from deterministic ODEs to stochastic drift–diffusion SDEs
\begin{eqnarray}\label{eq:sde1}
dX_t &=& b(X_t,t)\,dt + \sigma(X_t,t)\,dW_t, \qquad X_0 \sim \mu_0,
\end{eqnarray}
while preserving consistency in law for the surrogate dynamics of $\hat{X}_t$.

\label{sec:main idea}
\noindent  
To construct the reduced dynamics, the key ingredient is to use the {time-dependent projection operator}
\begin{eqnarray}
\label{eq:pro-time-dependent}
(P_t g)(\hat{X}_t) &=& \mathbb{E}_{\mu_t}[\,g(X)\mid \hat{X}=\hat{X}_t\,], \qquad g\in L^2(\Gamma,\mu_t),
\end{eqnarray}
defined as the conditional expectation with respect to the current probability measure $\mu_t$ and the current state of $\hat{X}_t$. This operator provides an optimal $L^2$-projection at each time and evolves adaptively along the probability flow, as illustrated in Figure \ref{fig:idea}. \\ \ \\
Applying $P_t$ to the drift of the resolved variables, $\hat{b}(X,t)$, yields the reduced dynamics
\begin{eqnarray}
\frac{d}{dt}\hat{X}_t&=& \mathbb{E}_{\mu_t}[\,\hat{b}(X,t)\mid \hat{X}=\hat{X}_t\,], \qquad \hat{X}_0\sim \hat{\mu}_0.
\end{eqnarray}
The resulting surrogate trajectories evolve consistently with the marginal law $\hat{\mu}_t$ of $\hat{X}_t$, and are therefore exact in distribution.  This property is established formally in Section \ref{sec:optimal proba consitstent reduced dynamics}. \\ \ \\
In contrast to the MZ formalism, our approach eliminates the intractable memory integral by continuously updating both the probability measure and the reference configuration, thereby ensuring that the random force remains orthogonal to the resolved space by construction and that the reduced dynamics are closed without additional assumptions (see Section \ref{sec:MZ}).

\\ \ \\ In practice, the probability law $\mu_t$ is not known explicitly, which raises the central challenge of computing the conditional expectations that define the reduced dynamics. Intuitively, it is often easier to approximate the evolution of the probability measure than that of individual trajectories: while sample paths may fluctuate irregularly, the associated measures typically evolve smoothly in time. To implement the framework, we approximate the probability flow $\mu_t$ using a Polynomial Chaos (PC) expansion of the state
\begin{eqnarray}
X_t &\approx& \sum_{\alpha} c_{\alpha,t} H_\alpha(\xi),
\end{eqnarray}
where, e.g. $\xi$ is a standard Gaussian random variable and $\{H_\alpha\}$ Hermite polynomials. The PC coefficients $c_{\alpha,t}$ evolve deterministically, resulting in an efficient representation of $\mu_t$. Conditional expectations are then computed by polynomial regression on the resolved variables, avoiding costly Monte Carlo sampling in low-probability regions. \\ \ \\
In summary, our method combines the following.
\begin{enumerate}
\item  A time-dependent optimal projection ensuring consistency in law.
\item Efficient computation of the probability flow via PC expansion. 
\item Affordable estimation of conditional expectation through polynomial regression. 
\end{enumerate}
The resulting workflow constitutes a trajectory-based reduction framework that retains the interpretability of projection methods while remaining  tractable for both ODEs and SDEs. Before establishing the theoretical results of this framework in Section \ref{sec:optimal proba consitstent reduced dynamics}, we present a detailed comparison with first-order optimal prediction and the MZ formalism.

\label{sec:assumptions}
\noindent The theoretical results of this section are subject to the following list of assumptions on the regularity of the drift and noise coefficients as well as on the probability flow $\{\mu_t\}_{0\leq t\leq T}$ Eq.~(\ref{eq:mut}) associated to Eqs.~(\ref{eq:ode assumption})-(\ref{eq:sde assumption}). 
For convenience we consider autonomous dynamical systems but the results can be generalized to non-autonomous dynamical systems provided sufficient regularity and controlled growth. 
For each theoretical result we mention which assumptions from the list below are needed.
\begin{enumerate}
    \item The vector field $b:\Gamma \to\mathbb{R}^N$ is globally Lipschitz on $\Gamma$, and continuous in time. 
    \item The noise coefficient $\sigma:\Gamma\to\mathbb{R}^{N\times N}$ is globally Lipschitz on $\Gamma$, and continuous in time. 
    \item The initial probability measure has finite second moment and absolutely continuous with respect to the Lebesgue measure i.e. $\mu_0\in\mathcal{P}^r_2(\Gamma)$.
    \item The conditional measures $\{\mu_{t|\hat{X}_t=x}\}$ exist and $\forall t\geq 0$ there exists $K_t\geq 0$ such that,
    \begin{eqnarray}
    \mathcal{W}_1(\mu_{t|\hat{X}_t=y},\mu_{0|\hat{X}_t=z})\leq K_t|y-z|, \quad \forall \ y,z \in \hat{\Gamma},
    \end{eqnarray}
    where $\mathcal{W}_1$ is the 1-Wassertein distance. 
\end{enumerate}
Note that the constraint on stability of the conditional measure results in the following. 
\begin{proposition}[Lipschitzness of Conditional Expectation]\label{prop:lipschitz mckean-vlasov}
Given the assumption (4), for any globally Lipschitz function $f:\Gamma\to\mathbb{R}$, there exists $C_t\geq 0, \ \forall t\geq0$ such that,  
\begin{eqnarray}
        \big|\mathbb{E}_{\mu_t}[f(X)\mid \hat{X}=y] - \mathbb{E}_{\mu_t}[f(X)\mid \hat{X}=z]\big|\leq C_t|y-z|,\: \forall \ y,z\in\hat{\Gamma}.
\end{eqnarray}
\end{proposition}
\begin{proof}
    See Appendix~\ref{app:condexp}
\end{proof}

\begin{theorem}[Trajectory Consistency for ODE]\label{thm:pseudo-mark}
    Consider the dynamical system Eq.~(\ref{eq:ode assumption}) and the choice of resolved variables $\hat{X}:=X_i$ for some $i\in \{1,...,N\}$. Let $\hat{b}:=b_i$ and $\hat{X}^0=X_i(t_0)$. Given assumptions (1), (3), we have the following.
    \begin{enumerate}
        \item Under suitable choice of $\zeta^n$ and for small $\Delta t>0$, the numerical scheme 
        \begin{eqnarray}\label{eq:scheme proposition}
            \hat{X}^{n+1} = \hat{X}^{n} +  \mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X}^n]\Delta t  + \zeta^n\Delta t, 
        \end{eqnarray}
        converges in the following sense: $\mathbb{E}[|\hat{X}^{n}-X_i(t_n)|^2]=O(\Delta t^2)$, where $X_i(t_n)$ is the exact solution at time $t_n$.
        \item The term $\zeta^n$ can be identified as a noise term in the following sense,
        \begin{eqnarray}
        \label{eq:noise-iden}
            \mathbb{E}_{\mu_t}[\zeta^n] = 0, \ 
            \mathbb{E}_{\mu_t}[\zeta^n\mid\hat{X}^n] = 0, \ \ \ \textrm{and} \ \ 
            \mathbb{E}_{\mu_t}\left[\zeta^n\:\mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X}^n]\right] = 0,
        \end{eqnarray}
        $\forall \:t\geq 0$.
    \end{enumerate}
\end{theorem}
\begin{proof}
    See Appendix.~\ref{proof:pseudomark}.
\end{proof}
\begin{corollary}[Trajectory Consistency for SDE] \label{corol:pseudo-mark-sde} Similar result would hold if $X_t$ is solution of the SDE Eq.~(\ref{eq:sde assumption}) fulfilling assumptions (1)-(3) .
\begin{enumerate}
\item For suitable choices of noise terms $\zeta^n$ and $\eta^n$, the scheme 
 \begin{eqnarray}
            \hat{X}^{n+1} = \hat{X}^{n} +  \mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X}^n]\Delta t+\mathbb{E}_{\mu_t}[\hat{\sigma}(X)|\hat{X}^n] \sqrt{\Delta t}\xi^n+\left(\zeta^n\Delta t+\eta^n \sqrt{\Delta t}\right), 
        \end{eqnarray}
        with $\xi^n$ as the standard normal random number, converges in the following sense: given identical Brownian path for $\hat{X}$ and $X$, $\mathbb{E}[|\hat{X}^n-X_i(t_n)|^2]=O(\sqrt{\Delta t})$. 
\item The terms $\zeta^n$ and $\eta^n$ can be identified as noise terms in the sense of fulfilling Eq.~\eqref{eq:noise-iden}.
\end{enumerate}        
\end{corollary}
\begin{proof}
    See Appendix.~\ref{proof:pseudomark sde}.
\end{proof}
\noindent \textbf{Remark:} these results can be extended to arbitrary $\mathcal{F}$-measurable smooth observables $A=(A_i)_{1\leq i\leq m}$, $A:\Gamma\to\hat{\Gamma}\in\mathbb{R}^m$ provided $LA$ and $\sum_{i,j=1}^ND_{ij}\frac{\partial A_k \partial A_l}{\partial x_j \partial x_i}$ are Lipschitz.

\begin{proposition}[Marginal Preservation: Deterministic Case]\label{prop:deterministic}
Let $X\in\Gamma\subseteq\mathbb{R}^N$ evolve according to the deterministic dynamics, Eq.~(\ref{eq:ode assumption}), with uncertain initial condition. Assume $b\in \mathcal{H}_t=L^2(\Gamma,\mu_t), \forall t \geq 0$ and let $\hat{b}:=(b_1,\dots,b_m)$. Let surrogate trajectories for the resolved variables $\hat{X}=(X_1,\dots,X_m)\in\mathbb{R}^m, \ m<N$ satisfy the reduced dynamics,
\begin{eqnarray}\label{eq:surrogate dynamics proposition}
    d\hat{X}_t = \mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X} = \hat{X}_t] \ dt, \ \qquad
    \hat{X}_0 \sim \hat{\mu}_0(d\hat{X}),
\end{eqnarray}
where we defined the initial marginal law $\hat{\mu}_0(\hat{X})=\int_{\hat{\Gamma}^\perp}d\mu_0(X)$, $\hat{X}\in\hat{\Gamma}$ and $\Gamma=\hat{\Gamma}\times\hat{\Gamma}^\perp$.
Then, given assumptions (1), (3)-(4), the surrogate trajectories preserve the marginal law $\hat{X}_t\sim\hat{\mu}_t, \forall t\geq 0$. 
Moreover, at each instant $t$, $\mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X} = \hat{X}_t]$ is the optimal projection of the vector field $b$ in $\mathcal{H}_t=L^2(\mathbb{R}^N,\mu_t)$, where $\mu_t$ is the probability measure of the full-order system at time $t$. 
\end{proposition}
\begin{proof}
    See Appendix.~\ref{app:proof x ode}.
\end{proof}

\begin{proposition}[Marginal Preservation: Stochastic Case]\label{prop:stochastic}
Consider the $\Gamma$-valued stochastic process $\{X_t\}_{t\geq 0}, \ X_t\in L^2(\Omega;\mathbb{R}^N)$, governed by the Itô SDE Eq.~(\ref{eq:sde assumption}). 
Suppose that $b,\sigma \in\mathcal{H}_t=L^2(\mathbb{R}^N,\mu_t),\forall t \geq 0$. Define the resolved variables $\hat{X}:=(X_1,\dots,X_m)\in\mathbb{R}^m, \ m<N$ and let $\hat{b}:=(b_1,\dots,b_m)$.
Then, given assumptions (1)-(4), the surrogate trajectories satisfying the reduced dynamics,
\begin{eqnarray}\label{eq:optimal prob consistent sde}
    d\hat{X}_t = \mathbb{E}_{\mu_t}[\hat{b}(X)\mid\hat{X}=\hat{X}_t]dt + \hat{\sigma}(\hat{X}_t)d\hat{W}_t, \quad
    \hat{X}_0 \sim \hat{\mu}_0,
\end{eqnarray}
for the resolved variables $\hat{X}$ preserve the marginal law $\hat{X}_t\sim\hat{\mu}_t, \forall t\geq 0$.
The matrix $\hat{\sigma}\in\mathbb{R}^{m \times q}$ satisfies $\frac{1}{2}\hat{\sigma}\hat{\sigma}^T = \mathbb{E}_{\mu_t}[\hat{D}\mid\hat{X}]$, where $\hat{D}\in\mathbb{R}^{m\times m}, \: \hat{D}_{ij}=D_{ij}, \: i,j\in\{1,\dots,m\}$ and $D\in\mathbb{R}^{N\times N}$ is the diffusion matrix related to the probability flow of $\mu_t$.
$\hat{W_t}$ is a $q$-dimensional Wiener process with independent components.
Moreover, the drift coefficient $b$ and the diffusion matrix $D$ are optimally projected at each instant $t\geq 0$.
\end{proposition}

\begin{proof}
See Appendix \ref{app:surrogate sde}.
\end{proof}

\noindent \textbf{Remark:} these results can be extended to arbitrary $\mathcal{F}$-measurable smooth observables $A=(A_i)_{1\leq i\leq m}$, $A:\Gamma\to\hat{\Gamma}\in\mathbb{R}^m$ of finite second moment, i.e. $A_t\in\mathcal{H}_t$.

\noindent For the case where $X_t$ solves the Itô SDE
\begin{equation}\label{eq:ito}
dX_t = b(X_t,t)\,dt + \sigma(X_t,t)\,dW_t, \qquad X_0 \sim \mu_0,
\end{equation}
the law $\mu_t$ can, under suitable assumptions \cite{gorjichaos}, be equivalently generated by the McKean–Vlasov ODE
\begin{equation}
dY_t = b(Y_t,t)\,dt - \tfrac{1}{2}\,\sigma^2(Y_t,t) 
\nabla_x \log\!\big(\sigma^2(Y_t,t)\,\rho_Y(y,t)\big)\big|_{y=Y_t}\,dt,
\end{equation}
where $\rho_Y$ is the density of measure induced by $Y_t$.
Inserting the PC expansion \eqref{eq:PC expansion} into this dynamics gives the evolution equations for the coefficients
\begin{align}\label{eq:coeff evolution SDE}
dc_{\alpha,i}(t) &= \mathbb{E}\left[\, b_i(M_t(\xi),t)\, H_\alpha(\xi)\,\right]\,dt \\
&\quad+ \tfrac{1}{2}\,\mathbb{E}\left[\, 
\sigma^2(M_t(\xi),t) 
\sum_{l=1}^N \frac{\partial M_{t,l}^{-1}}{\partial \xi_i} 
\frac{\partial H_\alpha(\xi)}{\partial \xi_l}
\,\right]\,dt, \nonumber
\end{align}
for $i=1,\dots,N$.  
Note that ${\partial M_{t,l}^{-1}}/{\partial \xi_i}$ denotes the $(l,i)$-entry of the inverse Jacobian of the random map $M_t$.

\noindent Instead of computing the conditional expectation pointwise, we approximate it in a \emph{weak sense}, i.e. for a chosen polynomial basis $\{\psi_\alpha(\hat{X})\}_\alpha$, $\mathbb{E}_{\mu_t}[\, b_j(X)\mid \hat{X}_t\,]\approx h_{\{\psi_\alpha\}}(\hat{X}_t)$ and we require
\begin{eqnarray}
\mathbb{E}_{\mu_t}\!\left[\, b_j(X)\,\psi_\beta(\hat{X}_t)\,\right] 
= \mathbb{E}_{\mu_t}\!\left[\, \mathbb{E}_{\mu_t}[\,b_j(X)\mid \hat{X}_t\,]\,\psi_\beta(\hat{X}_t)\,\right] \overset{!}{=} \mathbb{E}_{\mu_t}\left[\, h_{\{\psi_\alpha\}}(\hat{X}_t)\,\psi_\beta(\hat{X}_t)\,\right],
\end{eqnarray}
for all test functions $\psi_\beta$ in the basis.

\noindent We approximate $\mathbb{E}_{\mu_t}[\, b_j(X)\mid \hat{X}_t\,]$ by a polynomial expansion
\begin{eqnarray}
\label{eq:estimate_CE}
\mathbb{E}_{\mu_t}[\, b_j(X)\mid \hat{X}_t\,] &\approx& \sum_{\beta\in\mathcal{J}_r^m} a_{j,\beta}(t)\,\psi_\beta(\hat{X}_t),
\end{eqnarray}
where $\mathcal{J}_r^m$ is the set of multi-indices up to degree $r$.  
The coefficients $\{a_{j,\beta}(t)\}$ are determined by solving the linear system
\begin{eqnarray}\label{eq:linear system CE}
\sum_{\gamma\in\mathcal{J}_r^m} G_{\beta,\gamma}(t)\,a_{j,\gamma}(t)
= \mathbb{E}_{\mu_t}\!\left[\, b_j(X)\,\psi_\beta(\hat{X}_t)\,\right],
\qquad 
G_{\beta,\gamma}(t)=\mathbb{E}_{\mu_t}[\,\psi_\beta(\hat{X}_t)\psi_\gamma(\hat{X}_t)\,].
\end{eqnarray}
The Gram matrix $G(t)$ is symmetric and positive definite by construction, ensuring well-posedness.

\begin{itemize}
\item  \textbf{Well-established result:} Since the conditional expectation is the $L^2$-(optimal) projection onto functions of $\hat{X}$, the polynomial expansion in $\hat{X}$ is equivalent to performing a PC expansion with respect to the marginal law $\hat{\mu}_t$. As the polynomial degree $r\to\infty$,
PC expansions converge in $L^2$ and therefore the approximation \eqref{eq:estimate_CE} converges in $L^2(\hat{\mu}_t)$ to the exact conditional expectation. 
\item  \textbf{Heuristic choice:} In practice, we truncate the basis at degree $r$, and expectations are approximated using quadrature rule.  
\item  \textbf{Complexity:} The methods scales with the number of basis functions $\binom{m+r}{r}$, i.e. polynomially in the degree $r$ and combinatorially in the resolved dimension $m$. Since dependence is only on $m$and not on the unresolved dimension $(N-m)$, the online trajectory integration remains computationally efficient. 
\end{itemize}

\noindent We adopt an explicit Euler scheme for simplicity:
\begin{eqnarray}\label{eq:Reduced Dynamics Discretized}
\hat{X}_{t+\Delta t} = \hat{X}_t + \Delta t \, \mathbb{E}_{\mu_t}[\,\hat{b}(X)\mid \hat{X}_t\,].
\end{eqnarray}
Higher-order schemes (Runge–Kutta, implicit methods) can be employed if higher convergence rate accuracy is required. Here, we choose explicit Euler because the main source of numerical error arises from the truncation of the PC and the polynomial regression approximations rather than from the time discretization.

\label{sec:numerical experiments}
\noindent In this section, we present the results of several numerical experiments that demonstrate the effectiveness of the proposed Pseudo-Markovian scheme. The numerical experiments illustrate how the proposed pseudo-Markovian reduction performs across settings of different complexity. We begin with linear–Gaussian systems, where closed-form solutions allow a direct verification of marginal preservation and conditional accuracy . We then consider nonlinear dynamics with non-Gaussian initial measures, testing the method’s ability to track probability flows in a multimodal setting. Finally, we examine SDE setting, demonstrating the performance of the method in dynamics driven by White noise. Together, these examples verify accuracy, probability consistency, and efficiency of the method across representative scenarios. \\ \ \\
We focus on systems with polynomial drift terms $b(X)$ and constant noise coefficient matrices $\sigma$.
The overall solution strategy is summarized in Algorithm \ref{alg:solution algo}:
\begin{enumerate}
    \item \textit{Offline phase}. 
    The probability flow $\{\mu_t\}$ is first approximated using a PC expansion Eq:~(\ref{eq:PC expansion}) by solving Eq.~(\ref{eq:coeff evolution ODE}) or Eq.~(\ref{eq:coeff evolution SDE}), depending on whether the underlying dynamics is deterministic or stochastic.

    \item \textit{Online phase}. For any chosen set of resolved variables $A(X)$, we integrate the reduced dynamics Eq.~(\ref{eq:Reduced Dynamics Discretized}) using aforward Euler (ODE), or Euler-Maruyama (SDE) scheme to approximate $\mathbb{E}[\hat{X}_t\mid\hat{X_0}]$. 
    The projected drift term is represented by the polynomial expansion Eq.~(\ref{eq:estimate_CE}), with coefficient obtained solving the linear system Eq.~(\ref{eq:linear system CE}). These coefficients depend explicitly on the instantaneous value of the PC coefficients precomputed in the offline phase.
\end{enumerate}
\noindent\textbf{Remark.}
Note that in the experiment with nonlinear dynamics Eq.~(\ref{eq:nonlinear dynamics}), the drift term does not satisfy the global-Lipschitzness assumption of Section~\ref{sec:assumptions}. However, there exists a global Lyapunov function with negative time-derivative ensuring that $b(X)$ remains Lipschitz along trajectories (they remain in a compact set).
There is moreover a single asymptotically stable fixed point. We expect the possibility to extend our results to Lyapunov stable dynamical systems, as supported by the numerical experiment.

\label{sec:error estimate}
\noindent We now analyze the modeling error in $\mathbb{E}[\hat{X}_t\: | \: \hat{X}_0]$, introduced by the pseudo-Markovian approximation, Eq.~(\ref{eq:surrogate dynamics proposition}). We focus on the deterministic setting, while the stochastic case is discussed in Appendix \ref{app:error sde}. 
In the special case of a linear drift and of a Gaussian initial probability measure, the modeling error admits an explicit expression for the time evolution.
To derive it, we first write the exact evolution $\hat{X}^{exact}$ of the resolved components $\hat{X}=(X_1,\dots,X_m)\in\hat{\Gamma}\subset\mathbb{R}^m$,
\begin{eqnarray}\label{eq:exact resolved}
    \frac{d}{dt}\hat{X}^{exact}_t = \mathbb{E}_{\mu_t}[\hat{b}\mid \hat{X}^{exact}_t] + F_t,
\end{eqnarray}
with initial condition $\hat{X}^{exact}_0 = \hat{X}_0$ and
where the random force $F_t \in \mathbb{R}^m$ denotes the complement of the optimal projection that is orthogonal to the resolved drift $\hat{b}\in\mathbb{R}^m$ with respect to the conditional expectation operator  $\mathbb{E}_{\mu_t}[\:(\cdot)\mid\hat{X}_t\:]$.
\\ \ \\
The unresolved variables $\hat{X}_0^{\perp ,exact} \in\mathbb{R}^{N-m}$ are sampled from $\mu_{0|\hat{X}_0}$, the initial probability measure conditioned on $\hat{X}_0$.  
In this deterministic setting, a surrogate trajectory $\hat{X}^S_t$ is defined as the solution of Eq.~(\ref{eq:surrogate dynamics proposition}) with fixed initial condition $\hat{X}^{S}_0 = \hat{X}_0$.
It provides an approximation of the conditional expected trajectory $\mathbb{E}[\hat{X_t}\mid\hat{X}_0]$, whose exact evolution can be derived by taking the conditional expectation of Eq.~(\ref{eq:exact resolved}) with respect to $\hat{X}_0$,
\begin{eqnarray}
    \frac{d}{dt}\mathbb{E}[\hat{X}^{exact}_t\mid \hat{X}_0] = \mathbb{E}\left[\mathbb{E}_{\mu_t}[b\mid\hat{X}^{exact}_t] \:\big|\: \hat{X}_0 \right] + \mathbb{E}[F_t\mid\hat{X}_0],\quad
    \mathbb{E}[\hat{X}_0^{exact}\mid\hat{X}_0] = \hat{X}_0.
\end{eqnarray}
Defining the modeling error as $e(t)=\hat{X}^S_t-\mathbb{E}[\hat{X}^{exact}_t\mid\hat{X}_0]$, its evolution satisfies
\begin{eqnarray}
    \frac{d}{dt}e = \mathbb{E}_{\mu_t}[b\mid\hat{X}^S_t] - \mathbb{E}\left[\mathbb{E}_{\mu_t}[b\mid\hat{X}^{exact}_t] \mid \hat{X}_0 \right] - \mathbb{E}[F_t\mid\hat{X}_0],\quad
    e(0)=0.
\end{eqnarray}
For a linear system governed by Eq.~(\ref{eq:linear system ODE})
with Gaussian initial probability density $\mathcal{N}(m_0,\Sigma_0)$, the conditional expectation can be expressed explicitly, and we obtain
\begin{align}
    \frac{\mathrm{d}}{\mathrm{d}t} e(t) 
    &= Q(t)\, e(t) - \overline{F}(t), \label{eq:evolution_error} \\
    \overline{F}(t) 
    &:= \mathbb{E} [ F_t \mid \hat{X}_0 ], \label{eq:mean_force} \\
    Q(t) 
    &:= B_{\mathrm{res},\,\mathrm{res}} 
    + B_{\mathrm{res},\,\mathrm{unres}} 
    \left[ e^{Bt} \Sigma_0 e^{B^\top t} \right]_{\mathrm{unres},\,\mathrm{res}} 
    \left[ e^{Bt} \Sigma_0 e^{B^\top t} \right]^{-1}_{\mathrm{res},\,\mathrm{res}}, \label{eq:Q_def}
\end{align}
where, $m_0 \in \mathbb{R}^N$ and $\Sigma_0 \in \mathbb{R}^{N\times N}$ are the initial mean and covariance matrix, respectively.
The sub-matrix $B_{\mathrm{res},\,\mathrm{res}} \in \mathbb{R}^{m \times m}$ is obtained by selecting the rows and columns of $B$ corresponding to the resolved variables, whereas the sub-matrix $B_{\mathrm{res},\,\mathrm{unres}} \in\mathbb{R}^{m\times (N-m)}$ is obtained by selecting the rows corresponding to the resolved variables and the columns corresponding to the unresolved variables. The same subscript convention applies to the other sub-matrices appearing in Eq.~(\ref{eq:Q_def}). The matrix exponential, $e^{Bt}=\sum_{k=0}^\infty \frac{t^kA^k}{k!}\in \mathbb{R}^{N \times N}$ is assumed to yield a nonsingular sub-matrix $\left[ e^{Bt} \Sigma_0 e^{B^\top t} \right]_{\mathrm{res},\,\mathrm{res}}$  on $[0,T]$. Under these assumptions, the unique solution of Eq.~(\ref{eq:evolution_error}) is
\begin{eqnarray}\label{eq:error analytical}
    e(t) = -\int_0^t \Phi(t,\tau) \overline{F}(\tau)  d\tau, \ \ t\in[0,T],
\end{eqnarray}
where we defined the time-ordered exponential,
\begin{eqnarray}
    \Phi(t,\tau) = \mathcal{T}_{exp}\left(  \int_\tau^t Q(s)ds \right).
\end{eqnarray}
Figure \ref{fig:error modes} illustrates that, as the number $m$ of resolved variables increases, the surrogate trajectory $\hat{X}^S_{1,t}$ converges exponentially to $\mathbb{E}[\hat{X}_{1,t}^{exact}\mid\hat{X}_{1,0}]$, where $\hat{X}^S_{1,t}$, $\hat{X}_{1,t}^{exact}$ and $\hat{X}_{1,0}$ denote the first components of $\hat{X}_t^S$, $\hat{X}^{exact}_t$, and $\hat{X}_0$, respectively. 
When all variables of the original system are resolved, $m=N$, the surrogate trajectories are exact by construction.

\noindent For short times, Eq.~(\ref{eq:error analytical}) reduces to (see Appendix \ref{app:error}),
\begin{eqnarray}\label{eq:error short}
    e(t) =  -\frac{t^2}{2}\overline{F}'(0) + O(t^3),
\end{eqnarray}
where $\overline{F}'(0)$ is the time derivative of $\overline{F}$ at initial time. In Appendix \ref{app:error}, we derive an explicit expression for a two dimensional system.
Equation~(\ref{eq:error short}) is particularly useful to assess whether additional resolved variables are required to reach a prescribed accuracy over a short time horizon.

\label{app:condexp}
\begin{proof}[Proof of Proposition~\ref{prop:lipschitz mckean-vlasov} (Lipschitzness of Conditional Expectation)]
    Assume $f:\Gamma\to\mathbb{R}$ is globally Lipschitz. Then, for any $y,z\in\hat{\Gamma}$, we have,
    \begin{eqnarray}
        \big| \mathbb{E}_{\mu_t}[f(X)\mid \hat{X}=y] -  \mathbb{E}_{\mu_t}[f(X)\mid \hat{X}=z]\big| &=& \big| \mathbb{E}_{\mu_{t|\hat{X}=y}}[f(X)] -  \mathbb{E}_{\mu_{t|\hat{X}=z}}[f(X)]\big| \nonumber\\
        &\leq& C_{1,t}\mathcal{W}_1(\mu_{t|\hat{X}=y},\mu_{t|\hat{X}=z})\nonumber\\
        &\leq &C_t|y-z|,
    \end{eqnarray}
    where $C_{1,t},C_t>0, \forall t\geq 0$. The first inequality follows from Kantorovich-Rubinstein duality theorem \cite{Villani2009}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:pseudo-mark} (Trajectory Consistency for ODE)]\label{proof:pseudomark}
Fix $\zeta^n$ as the orthogonal complement to $\mathbb{E}_{\mu_t}[b(X)\mid \hat{X}^n]$, i.e. $\zeta^n:= \hat{b}(\hat{X}^n) - \mathbb{E}_{\mu_t}[\hat{b}(X)\mid \hat{X}^n]$, where the resolved variables $\hat{X}^n$ follow
the Pseudo-Markovian scheme,
    \begin{eqnarray}
        d\hat{X}^n=\mathbb{E}_{\mu_t}[\hat{b}(X)\mid \hat{X}_n]\Delta t + \zeta^n\Delta t, \quad \hat{X}^0 = X_{i,0}. 
    \end{eqnarray}

\begin{enumerate}

    \item Let $X(t_n)$ be the solution of
    \begin{eqnarray}
        \frac{d}{dt}X_t=b(X_t), \quad X_0\sim\mu_0(X)\in\mathcal{P}_2,
    \end{eqnarray}
    at time $t=t_n$ and let $X_i(t_n)$ be the corresponding solution for the resolved variable. Consider its approximation $X_i^n$ resulting from the first-order Euler scheme,
    \begin{eqnarray}
        dX^n=b(X^n)\Delta t, \quad X^0=X_0.
    \end{eqnarray}


    Then, from the definition of $\zeta^n$ and the Lipschitzness of $b$, we have,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^{n+1}-X_i^{n+1}|^2] &\leq& 3\mathbb{E}[|\hat{X}^{n}-X_i^{n}|^2] + 3\mathbb{E}[|\hat{b}(\hat{X}^n)-\hat{b}(X_i^n)|^2] \Delta t^2 \nonumber\\
        &\leq& (3 + C\Delta t^2)\mathbb{E}[|\hat{X}^{n}-X_i^{n}|^2] \nonumber\\
        &\leq&  (3 + C\Delta t^2)^{n+1} \mathbb{E}[|\hat{X}^{0}-X_i^{0}|^2] = 0,
    \end{eqnarray}
    which implies $\hat{X}^n=X^n_i \quad a.s. \quad \forall n$. Then,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^{n}-X_i(t_n)|^2] = \mathbb{E}[|{X}_i^{n}-X_i(t_n)|^2] = \mathbb{E}[|{\phi}_i^{n}(X_0)-\phi_i(t_n,X_0)|^2]
    \end{eqnarray}
    where we defined the (flow) maps $\phi^n(X_0):=X^n \ s.t. \ X^0=X_0$ and $\phi(t_n,X_0):=X(t_n) \ s.t. \ X(t_0)=X_0$. 
    Finally, since the first-order Euler scheme converges with rate $O(\Delta t)$ \cite{Süli_Mayers_2003}, we have,
    \begin{eqnarray}
        |\phi^n(X_0)-\phi(t_n,X_0)|^2 = O(\Delta t^2),
    \end{eqnarray}
    for any initial condition $X_0$. Noting that taking expectation preserves the rate, we have,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^n-X_i(t_n)|^2]=\mathbb{E}[|X^n-X(t_n)|^2] = \mathbb{E}_{\mu_0}[|{\phi}_i^{n}(X_0)-\phi_i(t_n,X_0)|^2] = O(\Delta t^2).
    \end{eqnarray}
    \item The first equality is proved using the law of total expectation. The second equality follows from the definition of $\zeta^n$ and the last equality is shown again using the law of total expectation.
\end{enumerate}
\end{proof}

\begin{proof}[Proof of Corollary~\ref{corol:pseudo-mark-sde} (Trajectory Consistency for SDE)]\label{proof:pseudomark sde}
Fix $\zeta^n$ as the orthogonal complement to $\mathbb{E}_{\mu_t}[b(X)\mid \hat{X}^n]$, i.e. $\zeta^n:= \hat{b}(\hat{X}^n) - \mathbb{E}_{\mu_t}[\hat{b}(X)\mid \hat{X}^n]$, and $\eta^n$ as the orthogonal complement to $\mathbb{E}_{\mu_t}[\hat{\sigma}(X)\mid \hat{X}^n]\xi^n$, i.e. $\eta^n:= \hat{\sigma}(\hat{X}^n)\xi^n - \mathbb{E}_{\mu_t}[\hat{\sigma}(X)\mid \hat{X}^n]\xi^n$, 
where $\xi^n$ is a standard normal random variable and the resolved variables $\hat{X^n}$ follow
the Pseudo-Markovian scheme,
    \begin{eqnarray}
        d\hat{X}^n=\mathbb{E}_{\mu_t}[\hat{b}(X)\mid \hat{X}_n]\Delta t + \mathbb{E}_{\mu_t}[\hat{\sigma}(X)\mid \hat{X}_n]\xi^n\sqrt{\Delta t} +(\zeta^n\Delta t + \eta^n\sqrt{\Delta t}), \quad \hat{X}^0 = X_{i,0}. 
    \end{eqnarray}

\begin{enumerate}

    \item Let $X(t_n)=:F_0^{t_n}(\int_0^{t_n}dW_t,X_0)$ be the solution of
    \begin{eqnarray}
        dX_t=b(X_t)dt+\sigma(X_t) dW_t, \quad X_0\sim\mu_0(X)\in\mathcal{P}_2,
    \end{eqnarray}
    at time $t=t_n$ with fixed realization of the Wiener process $\{W_t\}_{t\leq t_n}$ and let $X_i(t_n)=:F_{i,0}^{t_n}(\int_0^{t_n}d W_t,X_0)$ be the corresponding solution for the resolved variable. Consider its approximation $X_i^n=:F_{i}^n(\{\xi_k\}_{k\leq n},X_0)$ resulting from the first-order Euler-Maruyama scheme,
    \begin{eqnarray}
        dX^n=b(X^n)\Delta t + \sigma(X^n)\xi^n\sqrt{\Delta t}, \quad X^0=X_0.
    \end{eqnarray}


    Let $\hat{X}^n=:\hat{F}^n(n,\{\xi_k\}_{k\leq n},\hat{X_0})$ and fix the realization of the random process $\xi^n$.
    Then, from the definition of $\zeta^n$ and $\eta^n$, and the Lipschitzness of $b$ and $\sigma$, we have,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^{n+1}-X_i^{n+1}|^2] &\leq& 3\mathbb{E}[|\hat{X}^{n}-X_i^{n}|^2] + 3\mathbb{E}[|\hat{b}(\hat{X}^n)-\hat{b}(X_i^n)|^2] \Delta t^2 +3\mathbb{E}_{\mu_t}[|(\hat{\sigma}(\hat{X}^n)-\hat{\sigma}(X_i^n)){\xi^n}|^2]\Delta t\nonumber\\
        &\leq&3\mathbb{E}[|\hat{X}^{n}-X_i^{n}|^2] + 3\mathbb{E}[|\hat{b}(\hat{X}^n)-\hat{b}(X_i^n)|^2] \Delta t^2 +3\mathbb{E}_{\mu_t}[|\hat{\sigma}(\hat{X}^n)-\hat{\sigma}(X_i^n)|^2]\Delta t\nonumber\\
        &\leq& (3 + K\Delta t+ C\Delta t^2)\mathbb{E}[|\hat{X}^{n}-X_i^{n}|^2] \nonumber\\
        &\leq&  (3 + K\Delta t + C\Delta t^2)^{n+1} \mathbb{E}[|\hat{X}^{0}-X_i^{0}|^2] = 0,
    \end{eqnarray}
    which implies $\hat{X}^n=X^n_i \quad a.s. \quad \forall n$. Then,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^{n}-X_i(t_n)|^2] = \mathbb{E}[|{X}_i^{n}-X_i(t_n)|^2] = \mathbb{E}[|\hat{F}_i^{n}(\{\xi^k\}_{k\leq n},X_0)-F_0^{t_n}(\int_0^{t_n}dW_t,X_0)|^2].
    \end{eqnarray}
    Finally, since the first-order Euler-Maruyama scheme converges with rate $O({\Delta t})$ in $L^2$, we have,
    \begin{eqnarray}
        \mathbb{E}[|\hat{X}^n-X_i(t_n)|^2]&=&\mathbb{E}[|X^n-X(t_n)|^2] \nonumber\\
        &=& \mathbb{E}_{\mu_0}[|\hat{F}_i^{n}(\{\xi^k\}_{k\leq n},X_0)-F_0^{t_n}(\int_0^{t_n}dW_t,X_0)|^2]\nonumber \\
        &=& O(\Delta t^2).
    \end{eqnarray}
    \item The first equality is proved using the law of total expectation. The second equality follows from the definition of $\zeta^n$ and $\eta^n$, and the last equality is shown again using the law of total expectation.
\end{enumerate}


\end{proof}

\noindent\textbf{Deterministic dynamics}\label{app:proof x ode}

\begin{proof}[Proof of Proposition~\ref{prop:deterministic} (Marginal Preservation: Deterministic Case)]
    Let the full-order state vector $X\in\Gamma \subseteq \mathbb{R}^N$. Consider the dynamical system 
    \begin{eqnarray}
        \frac{dX}{dt} = b(X), \quad X(t=0) = X_0 \sim \mu_0,
    \end{eqnarray}
    where $b:\mathbb{R}^N\to\mathbb{R}^N$. Let $\hat{X}=(X_1,\dots,X_m), \ m<N$.
    Then, for any $g(\hat{X})\in C_0^\infty(\hat{\Gamma})$, we have,
    \begin{eqnarray}
        \frac{d}{dt}g = \sum_{i=1}^N b_i\partial_{x_i}g.
    \end{eqnarray}
    Therefore,
    \begin{eqnarray}
        \int_\Gamma \frac{d}{dt}g \ d\mu = \int_\Gamma \sum_{i=1}^N b_i        \frac{d}{dt}g = \sum_{i=1}^N b_i\partial_{x_i}g \ d\mu.
    \end{eqnarray}
    Since it is assumed that $\mu(X)$ admits a density $\rho(x)$, we get,
    \begin{eqnarray}
        \int_\Gamma g(\hat{x}) \ \partial_t\rho \ dx =  \int_{\hat{\Gamma}} g(\hat{x}) \ \partial_t\hat{\rho} \ d\hat{x} &=& \int_\Gamma \sum_{i=1}^N b_i\partial_{x_i}g(\hat{x}) \rho \ dx\nonumber\\
        &=&\int_{\hat{\Gamma}} \sum_{i=1}^m\mathbb{E}_{\mu_t}[b_i\mid \hat{x}] (\partial_{x_i}g) \hat{\rho}\ d\hat{x}\nonumber\\
        &=& -\int_{\hat{\Gamma}} g \sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{x}] \hat{\rho})\ d\hat{x},
    \end{eqnarray}
    where $\hat{\rho}(\hat{x}):=\int_{\hat{\Gamma}^\perp}\rho\ d\hat{x}^\perp$. This relation holds for any $g(\hat{X})\in C_0^\infty(\hat{\Gamma})$. Therefore, $\hat{\rho}$ is a weak solution of, 
    \begin{eqnarray}\label{eq:proba flow reference}
        \partial_tp+ \sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{x}] p)=0.
    \end{eqnarray}
    Similarly, suppose $Y\in\hat{\Gamma}\subseteq\mathbb{R}^m$ satisfies the reduced dynamics,
    \begin{eqnarray}
        \frac{d}{dt}Y=\mathbb{E}_{\mu_t}[\hat{b}\mid  Y], \quad Y_0\sim \hat{\nu}_0 = \hat{\mu}_0
    \end{eqnarray}
    where $\hat{b}:=(b_1,\dots,b_m)$ and the law of $Y$ is $\hat{\nu}$, which is assumed to admit a density $f(y)$. Then, following the same reasoning, for any $h(Y)\in C_0^\infty(\hat{\Gamma})$, we have,
    \begin{eqnarray}
        \frac{d}{dt}h = \sum_{i=1}^m \mathbb{E}_{\mu_t}[b_i\mid Y]\partial_{x_i}h,
    \end{eqnarray}
    and,
    \begin{eqnarray}
         \int_{\hat{\Gamma}} h \ \partial_tf \ dy = -\int_{\hat{\Gamma}} h \sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{y}] f)\ dy.
    \end{eqnarray}
    Hence, $f$ is also a weak solution of Eq.~(\ref{eq:proba flow reference}).
    Therefore, $\hat{X}$ and $Y$ are equal in law.
    Finally, by the orthogonal projection theorem in Hilbert spaces, the time-dependent conditional expectation $\mathbb{E}_{\mu_t}[(\cdot)\mid\hat{X}=\hat{X}_t]$ provides the best $L^2$-approximation in $\hat{\mathcal{H}}_t$ of any function in $\mathcal{H}_t$, $\forall t \geq 0$. Hence, the vector field $b$ is optimally projected in a time-dependent fashion.
\end{proof}

\noindent\textbf{Stochastic dynamics}\label{app:surrogate sde}
\begin{proof}[Proof of Proposition~\ref{prop:stochastic} (Marginal Preservation: Stochastic Case)]
    Let the full-order state vector $X\in\Gamma \subseteq \mathbb{R}^N$. Consider the Itô SDE, 
    \begin{eqnarray}
        dX_t = b(X_t)dt+\sigma(X_t)dW_t, \quad X(t=0) = X_0 \sim \mu_0,
    \end{eqnarray}
    where $b:\mathbb{R}^N\to\mathbb{R}^N$ and $\sigma:\Gamma\to\mathbb{R}^{N\times N}$. Let $\hat{X}=(X_1,\dots,X_m), \ m<N$.
    Then, for any $g(\hat{X})\in C_0^\infty(\hat{\Gamma})$, we have by Itô's lemma,
    \begin{eqnarray}
        dg(X_t) = Lg(X_t)dt + \sum_{i,j=1}^N\partial_{x_i}g(\hat{X}_t)\sigma_{ij}({X}_t)dW_{j,t},
    \end{eqnarray}
    where $ L=\sum_i b_i \,\partial_{x_i} + \sum_{i,j} D_{ij}\,\partial_{x_i}\partial_{x_j}$ is the generator is of the stochastic process and $D=\tfrac12 \sigma\sigma^\top$. Taking the expectation, we obtain,
    \begin{eqnarray}
        \frac{d}{dt}\mathbb{E}[g(X_t)]=\mathbb{E}[Lg(X_t)].
    \end{eqnarray}
    Assuming the law of $X_t$ admits a density $\rho(x)$, we can write,
    \begin{eqnarray}
        \int_{\hat{\Gamma}} g(\hat{x}) \ \partial_t\hat{\rho} \ d\hat{x} 
        &=&\int_\Gamma g(\hat{x}) \ \partial_t\rho \ dx  \nonumber\\
        &=& \int_\Gamma (Lg(\hat{x})) \rho \ dx\nonumber\\
        &=& \int_\Gamma (\sum_{i=1}^N b_i\partial_{x_i}g(\hat{x}) +\sum_{i,j=1}^N D_{ij}\partial_{x_i}\partial_{x_j} g(\hat{x}))\rho \ dx \nonumber\\
        &=&\int_{\hat{\Gamma}} \left(\sum_{i=1}^m\mathbb{E}_{\mu_t}[b_i\mid \hat{x}] \partial_{x_i}g \ + \ \sum_{i,j=1}^m \mathbb{E}_{\mu_t}[D_{ij}\mid \hat{x}]\partial_{x_i}\partial_{x_j} g \right)\hat{\rho} \ d\hat{x} \nonumber\\
        &=& \int_{\hat{\Gamma}} g \left(-\sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{x}]\hat{\rho})\ + \sum_{i,j=1}^m \partial_{x_i}\partial_{x_j}(\mathbb{E}_{\mu_t}[D_{ij}\mid \hat{x}] \hat{\rho}) \right)\ d\hat{x},
    \end{eqnarray}
    where $\hat{\rho}(\hat{x}):=\int_{\hat{\Gamma}^\perp}\rho\ d\hat{x}^\perp$. This relation holds for any $g(\hat{X})\in C_0^\infty(\hat{\Gamma})$. Therefore, $\hat{\rho}$ is a weak solution of, 
    \begin{eqnarray}\label{eq:proba flow sde reference}
        \partial_tp=- \sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{x}] p)+\sum_{i,j=1}^m \partial_{x_i}\partial_{x_j}(\mathbb{E}_{\mu_t}[D_{ij}\mid \hat{x}]p).
    \end{eqnarray}
    Similarly, suppose $Y\in\hat{\Gamma}\subseteq\mathbb{R}^m$ satisfies the reduced stochastic dynamics,
    \begin{eqnarray}
        dY_t=\mathbb{E}_{\mu_t}[\hat{b}\mid  Y_t]dt + \mathbb{E}_{\mu_t}[\hat{\sigma}\mid Y_t]d\hat{W}_t, \quad Y_0\sim \hat{\nu}_0 = \hat{\mu}_0,
    \end{eqnarray}
    where $\hat{b}:=(b_1,\dots,b_m)$, $\hat{\sigma}:=\sigma_{ij}, \ i,j=\{1,\dots,m\}$ and the law of $Y_t$ is $\hat{\nu}_t$, which is assumed to admit a density $f(y)$. Then, following the same reasoning, for any $h(Y)\in C_0^\infty(\hat{\Gamma})$, we have,
    \begin{eqnarray}
        \frac{d}{dt}\mathbb{E}[h] = \mathbb{E}\bigg[\sum_{i=1}^m \mathbb{E}_{\mu_t}[b_i\mid Y]\partial_{x_i}h + \sum_{i,j=1}^m\mathbb{E}_{\mu_t}[D_{ij}\mid Y]\partial_{x_i}\partial_{x_j} h  \bigg],
    \end{eqnarray}
    and,
    \begin{eqnarray}
         \int_{\hat{\Gamma}} h \ \partial_tf \ dy = \int_{\hat{\Gamma}} h \left(-\sum_{i=1}^m\partial_{x_i}(\mathbb{E}_{\mu_t}[b_i\mid \hat{y}] f) + \sum_{i,j=1}^m\partial_{x_i}\partial_{x_j}(\mathbb{E}_{\mu_t}[D_{ij}\mid Y] f) \right)\ dy.
    \end{eqnarray}
    Hence, $f$ is also a weak solution of Eq.~(\ref{eq:proba flow sde reference}).
    Therefore, $\hat{X}$ and $Y$ are equal in law.
    Finally, by the orthogonal projection theorem in Hilbert spaces, the time-dependent conditional expectation $\mathbb{E}_{\mu_t}[(\cdot)\mid\hat{X}=\hat{X}_t]$ provides the best $L^2$-approximation in $\hat{\mathcal{H}}_t$ of any function in $\mathcal{H}_t$, $\forall t \geq 0$. Hence, the generator is optimally projected in a time-dependent fashion.
\end{proof}

\label{app:error sde}
\noindent We generalize the analysis of the modeling error, arising from the approximation of the evolution of the quantity $\mathbb{E}[\hat{X}_t\mid \hat{X}_0]$ with our pseudo-Markovian reduced dynamics Eq.~\eqref{eq:optimal prob consistent sde} , when the latter is built on the stochastic process, Eq.~(\ref{eq:sde assumption}), at the micro-scale. We derive the result for a constant noise coefficient matrix $\sigma\in \mathbb{R}^{N\times q}$. In this case $\hat{\sigma}=\sigma_{res}$, where $\hat{\sigma}:\frac{1}{2}\sigma\sigma^T=D_{res}$ and $\sigma_{res}$ and $D_{res}$ are respectively the sub-matrices of $\sigma$ and $D$ formed by selecting the rows and columns corresponding to the resolved components. 
To compute the modeling error, we start by writing the exact evolution of the resolved components $\hat{X}=(X_1,\dots,X_m)\in\mathbb{R}^m$,
\begin{eqnarray}\label{eq:exact resolved sde}
    \frac{d}{dt}\hat{X}^{exact}_t = \mathbb{E}_{\mu_t}[\hat{b}(X^{exact})\mid\hat{X}^{exact}_t] + \hat{\sigma}dW_t  + F_t,
\end{eqnarray}
with the initial condition $\hat{X}^{exact}_0 = \hat{X}_0$ and
where the $\mathbb{E}_{\mu_t}[\:(\cdot)\mid\hat{X}_t\:]$-orthogonal random force $F_t \in \mathbb{R}^m$ is simply the orthogonal complement of our optimal projection of the resolved components $\hat{b}\in\mathbb{R}^m$ of the drift vector $b \in \mathbb{R}^N$. 
The unresolved variables $\tilde{X}_0^{exact} \in\mathbb{R}^{N-m}$ are sampled from $\mu_{0|\hat{X}_0}$, the initial probability measure conditioned on $\hat{X}_0$.  
A surrogate trajectory $\hat{X}^S_t$ is a solution of Eq.~(\ref{eq:optimal prob consistent sde}), with initial condition $\hat{X}^{S}_0 = \hat{X}_0$.
It is an approximation of the quantity $\mathbb{E}[\hat{X_t}\mid\hat{X}_0]$, whose exact evolution is derived by taking the conditional expectation of Eq.~(\ref{eq:exact resolved sde}), given $\hat{X}_0$,
\begin{eqnarray}
    \frac{d}{dt}\mathbb{E}[\hat{X}^{exact}_t\mid\hat{X}_0] = \mathbb{E}\left[\mathbb{E}_{\mu_t}[\hat{b}(X^{exact})\mid\hat{X}^{exact}_t] \:\bigg|\: \hat{X}_0 \right] + \mathbb{E}[F_t\mid\hat{X}_0],\\
    \mathbb{E}[\hat{X}_0^{exact}\mid\hat{X}_0] = \hat{X}_0.
\end{eqnarray}
Defining the error as $e(t)=\hat{X}^S_t-\mathbb{E}[\hat{X}^{exact}_t\mid\hat{X}_0]$, its evolution is governed by,
\begin{eqnarray}
    \frac{d}{dt}e = \mathbb{E}_{\mu_t}[\hat{b}(X^S)\mid\hat{X}^S_t] - \mathbb{E}\left[\mathbb{E}_{\mu_t}[\hat{b}(X^{exact})\mid\hat{X}^{exact}_t] \:\bigg|\: \hat{X}_0 \right] - \mathbb{E}[F_t\mid\hat{X}_0],\\
    e(0)=0.
\end{eqnarray}
For a linear system governed by $\frac{d}{dt}X=BX+\sigma dW_t$, $B \in\mathbb{R}^{N\times N}$, with initial Gaussian probability measure $\mathcal{N}_X(m_0,\Sigma_0)$, we obtain,
\begin{align}
    \frac{\mathrm{d}}{\mathrm{d}t} e(t) 
    &= Q(t)\, e(t) - \overline{F}(t), \label{eq:evolution_error sde} \\
    \overline{F}(t) 
    &:= \mathbb{E} \left[ F_t \,\mid \hat{X}_0 \right], \label{eq:mean_force_stoch} \\
    Q(t) 
    &:= B_{\mathrm{res},\,\mathrm{res}} 
    + B_{\mathrm{res},\,\mathrm{unres}} 
    \Sigma(t)_{\mathrm{unres},\,\mathrm{res}} 
    \Sigma(t)^{-1}_{\mathrm{res},\,\mathrm{res}}, \label{eq:Q_def_sde}
\end{align}
where, $m_0 \in \mathbb{R}^N$ and $\Sigma_0 \in \mathbb{R}^{N\times N}$ are the initial mean and positive semi-definite covariance matrix, respectively.
We defined $B_{\mathrm{res},\,\mathrm{res}} \in \mathbb{R}^{m \times m}$ as the $m\times m$ sub-matrix of $B$, obtained by selecting the rows and columns corresponding to the resolved variables. Similarly, $B_{\mathrm{res},\,\mathrm{unres}} \in\mathbb{R}^{m\times (N-m)}$ is the $m\times (N-m)$ sub-matrix of $B$, obtained by selecting the rows of $B$ corresponding to the resolved variables and the columns of $B$ corresponding to the unresolved variables. The same logic applies to the other sub-matrices appearing in Eq.~(\ref{eq:Q_def}). Moreover, $e^{Bt}\in \mathbb{R}^{N \times N}$ is the matrix exponential, $e^{Bt}=\sum_{k=0}^\infty \frac{t^kB^k}{k!}$.
The covariance matrix $\Sigma(t)$ is governed by the Lyapunov equation,
\begin{eqnarray}
    \frac{d}{dt}\Sigma = B\Sigma^T + \Sigma B^T + \sigma\sigma^T,
\end{eqnarray}
whose explicit solution is given by,
\begin{eqnarray}
    \Sigma(t)=e^{Bt}\Sigma(0)e^{B^Tt} + \int_0^te^{B(t-s)}\sigma\sigma^Te^{B^T(t-s)}ds.
\end{eqnarray}
Finally, the solution of Eq.~(\ref{eq:evolution_error sde}) is given by,
\begin{eqnarray}\label{eq:error analytical sde}
    e(t) = -\int_0^t \Phi(t,\tau) \overline{F}(\tau)  d\tau,
\end{eqnarray}
where we defined the time-ordered exponential,
\begin{eqnarray}
    \Phi(t,\tau) = \mathcal{T}_{exp}\left(  \int_\tau^t Q(s)ds \right).
\end{eqnarray}
Equation~(\ref{eq:error short}) is therefore still valid in this stochastic setting provided Eq.~(\ref{eq:Q_def_sde}) is used for the definition of $Q(t)$.

\begin{algorithm}[H]
\caption{Surrogate trajectories along probability flows}
\label{alg:solution algo}
\begin{algorithmic}[1]
\Require System dimension $N\in\mathbb{N}^+$, number of resolved variables $m<N$, polynomial drift coefficient $b\in\mathbb{R}^N$, constant noise coefficient matrix $\sigma\in\mathbb{R}^{N\times N}$, initial full-order probability measure $\mu_0$, initial condition for the resolved variables $\hat{X}_0\in \mathbb{R}^m$, time step $\mathrm{dt}>0$, number of samples $N_s\in\mathbb{N}^+$, PC expansion truncation total order $p\in\mathbb{N}^+$, conditional expectation polynomial expansion truncation total order $r\in\mathbb{N}^+$, quadrature points $\{q_k\}_{k\in K}$

\Statex 

\Statex \textbf{Offline Phase: probability flow}
\State Fit initial PC coefficients $c_j(0), \forall j\in \mathcal{I}_p^d$ to $\mu_0$

\For{$\tau = 0$ to $n_\tau$}

    \State Gaussian integrals: $I^{(1)}_{j,i}\leftarrow\mathbb{E}[b_iH_j]$ with analytical expressions
    \State Inverse of Jacobian matrix $(\frac{\partial M}{\partial \xi})^{-1}$ of the truncated PC expansion at quadrature points $\{q_k\}_{k\in K}$
    \State Gaussian integrals: $I^{D}_{j,i}\leftarrow\frac{1}{2} \mathbb{E} [ 
    \sigma^2 
    \sum_{l=1}^N\frac{\partial M_{t,l}^{-1}}{\partial \xi_i} 
    \frac{\partial H_j}{\partial \xi_l} 
    ]$ with Gauss-Hermite quadrature
    \State Euler increment: $c_{j,i}((\tau+1)\mathrm{dt}) \leftarrow c_{j,i}(\tau\mathrm{dt}) + I^{(1)}_{j,i} \mathrm{d}t + I^{D}_{j,i}\mathrm{d}t$
\EndFor
\vspace{0.2cm}
\Statex \textbf{Online Phase: surrogate trajectories}
\State $\hat{\sigma}_{i,j}=\sigma_{i,j}, \: i,j=\{1,\dots,m\}$
\For{$s=1$ to $N_s$}
    \State Initial condition: $\hat{X}\leftarrow\hat{X}_0$

    \For{$T = 0$ to  $n_\tau$}

        \State Gaussian integrals: $I^{(2)}$ and $I^{(3)}$ with analytical expressions
        \State Solve linear system: $\sum_{l\in\mathcal{J}_r^m}I^{(2)}_{k,l}\ \Bar{c}_{\alpha,j}(t) = I^{(3)}_{l,j}, \ \forall  j=\{1,..m\}, \ k\in \mathcal{J}_r^m$
        \State Polynomial expansion: $\mathbb{E}[\hat{b} \mid \hat{X}]\leftarrow\sum_{\beta\in\mathcal{J}_r^m}\Bar{c}_\alpha\Bar{H}_{\alpha}(\hat{X})$ 

        \State Wiener increment: $dW \sim \sqrt{dt}\ \mathcal{N}(0,I_m)$
        \State Euler-Maruyama increment: $\mathrm{d}\hat{X} \leftarrow \mathbb{E}[b \mid \hat{X}]\,\mathrm{dt} + \hat{\sigma}\,\mathrm{d}\hat{W}$
        \State $\hat{X}^{(s)} \leftarrow \hat{X}^{(s)} + \mathrm{d}\hat{X}$
    \EndFor
\EndFor
\State Averages: $\mathbb{E}[\hat{X}_{t=Tdt}\mid\hat{X}_0]\leftarrow \frac{1}{N_s}\sum_{s=1}^{N_s}X^{(s)}_{Tdt}, \ T=\{0,\dots,n_\tau\}$ 
\end{algorithmic}
\end{algorithm}



